// news-image-20261123 — "THE WORLD IN ONE DAY — 23 November 2026"
// Fresh program written 23 Nov 2026 in the competition window.
// Writes the entry image (1024x1024 PNG) to /output/entry.png.
//
// The image was rendered deterministically from stories.json by render.py
// (Python + PIL, fixed fonts, fixed layout, no network, no timestamps)
// and is embedded here as base64 so this program is self-contained,
// deterministic and network-free: every run writes identical bytes.
// Run: node main.ts   (MAKEFUN_OUTPUT_DIR overrides the output directory)
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const PNG_BASE64 = "";

const here = dirname(fileURLToPath(import.meta.url));
const outDir = process.env.MAKEFUN_OUTPUT_DIR ?? join(here, "output");
mkdirSync(outDir, { recursive: true });
const outPath = join(outDir, "entry.png");
writeFileSync(outPath, Buffer.from(PNG_BASE64, "base64"));
console.log("wrote " + outPath);
